arguments.command:
cd /app; cat migrations/0007* migrations/0008* migrations/0009* migrations/0010*; python3 - <<'E'
import csv,glob
for f in glob.glob('seeds/*.csv'):
    b=open(f,'rb').read()
    try: b.decode('utf-8'); print(f,'utf8 ok')
    except Exception as e: print(f,'not utf8')
    print(f, set(r for r in csv.reader(open(f,encoding='latin-1')) if 0) )
E
cut -d, -f8 seeds/specimens.csv | sort | uniq -c; grep -c . seeds/*.csv; sqlite3 -version; python3 -c "
import sqlite3;c=sqlite3.connect('releases/1.6.0/herbarium.sqlite');print(c.execute('select sql from sqlite_master').fetchall())"

